{
  "packet_id": "H6-T01-3",
  "claim_id": "C028",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C028.component",
    "value": "Calendar availability by itself is insufficient to establish physical readiness.",
    "scope": "An evidential limit on the calendar, not a claim that calendar entries are always inaccurate.",
    "provenance": {
      "refs": [
        {
          "source_id": "P018",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span directly expresses the calendar's evidential insufficiency."
    }
  },
  "signal_basis": {
    "component_id": "C028.signal_basis",
    "value": "Independent observations concerning the same equipment, booking and handoff can corroborate actual return or cleaning status; calendar availability alone does not verify physical readiness.",
    "scope": "Evidence of equipment status at the relevant scheduled start, without inferring the cause of lateness.",
    "provenance": {
      "refs": [
        {
          "source_id": "P016",
          "role": "SUPPORT"
        },
        {
          "source_id": "P017",
          "role": "SUPPORT"
        },
        {
          "source_id": "P018",
          "role": "SUPPORT"
        },
        {
          "source_id": "P031",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans identify the independent status checks, their booking-specific scope, the calendar's limitation and the restriction on causal inference."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C028.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No conditional empirical relation is needed for this supported evidential limit."
    }
  },
  "rationale": "Recorded availability and physical readiness are distinct states. The described checks provide evidence about actual return and cleaning that an availability entry alone does not establish. This licenses the narrow insufficiency claim without implying that every calendar entry is inaccurate.",
  "uncertainty": "The claim leaves the accuracy of any particular calendar entry unresolved.",
  "anomalies": []
}
